template <typename T>
float min(T& first, T& second)
{
	if (second < first)
	{
		first = second;
	}

	return first;
}

template <typename T>
float max(T& first, T& second)
{
	if (first < second)
	{
		first = second;
	}

	return first;
}

template<typename T>
float decay(T base, T power, T& result, const T& original)
{
	float exp = expf(base * power);
	return result = original + (result - original) * exp;
}

/* _close_enough<f> 0x19d950, _close_enough<i> 0x26c8d0: |value - target| <= eps (was a
 * provisional close_enough with the wrong test and no callers) */
template<typename T>
bool _close_enough(const T& value, const T& target, const T& eps)
{
	T d = value - target;
	return !(d < -eps) && d <= eps;
}

template<typename T>
bool saturate(T& value, T min, T max)
{
	if (!(value <= max)) /* _saturate<f> 0x1a8dd0: the ELF's form (a NaN is set to max) */
	{
		value = max;
		return true;
	}

	if (value < min)
	{
		value = min;
		return true;
	}

	return false;
}

