	void SetZero();

public:
	f32 m_matrix[4][4];
	/* @socom-skeleton decl 7CMatrix */
public:
	void SetRotate(const CPnt3D *);
	CQuat * ToQuat(CQuat *) const;
	void ToEuler(CPnt3D *) const;
	/* @socom-skeleton end 7CMatrix */
